				"**天相（落陷）** 在仆役：",
				"交友宫天相，朋友忠厚可靠，社交圈质量稳健；下属踏实，执行力和配合度好，是好的团队成员。少有利用关系的情况，朋友关系中以真诚互助为主；合伙人是稳健的行政型搭档。",
