				"交友宫七杀，朋友少而精，交际圈中多是同样强势独立的实干派；下属执行力强但关系较为疏离。朋友给你的是并肩战斗的战友情，而非细腻的情感支持；化忌则朋友关系因强势冲突而破裂，独行反而更自在。",
				"**天相** 在仆役：",
				"交友宫天相，朋友忠厚可靠，社交圈质量稳健；下属踏实，执行力和配合度好，是好的团队成员。少有利用关系的情况，朋友关系中以真诚互助为主；合伙人是稳健的行政型搭档。",
				"✦ 文曲：朋友多情感型人物，需防桃花是非。",
