				"✦ 天马：朋友圈散布各地，异地合伙多。",
				"**贪狼化忌（庙旺）** 在仆役：",
				"交友宫贪狼，朋友圈广泛，多才艺、欲望活跃型朋友；社交活跃，酒色财气的圈子影响较大，需善加筛选。化禄则人脉广财；化忌则朋友带来欲望是非，合伙因利益纠纷破裂。",
				"▶ 化忌：化忌，欲望受阻，感情波折大，烂桃花多，需谨慎处理感情关系，防财色两空。",
				"**天府** 在仆役：",
				"交友宫天府，朋友稳重可靠，社交圈质量高，多结交有财力或社会地位的稳健型朋友；下属踏实，执行力有保障。但朋友关系保守，少有冒险合作，需平衡稳健与创新。",
				"✦ 天魁：朋友中长辈或男性导师型多。",
				"✦ 左辅：朋友圈中有实在的得力助手。",
				"**破军化禄** 在仆役：",
				"交友宫破军，朋友圈流动性极强，不同阶段的朋友完全不同；下属难以稳定，合伙人各自为战。朋友带来的是变革和突破，而非稳定的支持；化禄则朋友在变动中帮助建立新局；化忌则朋友带来破坏，合伙损财。",
				"▶ 化禄：化禄，破而后立，逆境中开创财源，是破军最好的状态，在打破中建立新的格局。",
